def find_minimal_edit(s_in, s_out):
    """Find the minimal edit needed to transform s_in to s_out"""
    # Find first position where strings differ
    min_len = min(len(s_in), len(s_out))

    # Find the first difference
    pos = -1
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            pos = i
            break

    # If no difference found in common length, check lengths
    if pos == -1:
        if len(s_in) != len(s_out):
            pos = min_len
        else:
            return None  # Strings are identical

    # Find what needs to be replaced
    # Try to find a substring that matches the pattern
    old_sub = ""
    new_sub = ""

    # Look for the longest matching pattern
    for i in range(pos, min(len(s_in), len(s_out))):
        if s_in[pos:i+1] == s_out[pos:pos+len(s_in[pos:i+1])]:
            old_sub = s_in[pos:i+1]
            new_sub = s_out[pos:pos+len(s_in[pos:i+1])]

    # If we couldn't find a match, try character by character
    if not old_sub:
        old_sub = s_in[pos]
        new_sub = s_out[pos]

    return (old_sub, new_sub, pos)

# Analyze each changed pair
changed_pairs = [(0, 'hakb', 'hibwub'), (2, 'awu', 'ibwwu'), (3, 'afibi', 'ibwfibi')]

for idx, inp, outp in changed_pairs:
    result = find_minimal_edit(inp, outp)
    print(f"Pair {idx} ('{inp}' -> '{outp}'): {result}")

